<?php require '../common.php';startpage('Bus Comments');nav('<a href="index.php">Search buses</a>');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['bus_id'];$person=trim($_POST['person']);$comment=trim($_POST['comment']);$s=$conn->prepare('INSERT INTO bus_comments(bus_id,person,comment) VALUES(?,?,?)');$s->bind_param('iss',$id,$person,$comment);$s->execute();$msg='Comment posted.';}?><form method="post"><label>Bus<select name="bus_id"><?php $buses=$conn->query('SELECT * FROM buses');while($b=$buses->fetch_assoc()):?><option value="<?=$b['id']?>"><?=e($b['bus_name'])?> (<?=e($b['origin'])?>–<?=e($b['destination'])?>)</option><?php endwhile;?></select></label><input name="person" placeholder="Your name" required><input name="comment" placeholder="Comment" required><button>Post</button></form><?php if($msg)echo '<p class="msg">'.e($msg).'</p>';$rs=$conn->query('SELECT c.*,b.bus_name FROM bus_comments c JOIN buses b ON b.id=c.bus_id ORDER BY c.id DESC');?><table><tr><th>Bus</th><th>Name</th><th>Comment</th></tr><?php while($r=$rs->fetch_assoc()):?><tr><td><?=e($r['bus_name'])?></td><td><?=e($r['person'])?></td><td><?=e($r['comment'])?></td></tr><?php endwhile;?></table><?php endpage();?>